
select "T0"."C0" "Order_Number", "T0"."C1" "Line_Number", "T0"."C2" "Ordered_Date", "T0"."C3" "Promised_Ship_Date", "T0"."C4" "CSR_Name", "T0"."C5" "Customer_Name", "T0"."C6" "C_2nd_Item_Number", "T0"."C7" "Description_1", "T0"."C7" "Description_2", "T0"."C8" "Delivery_Instructions_Line_1", "T0"."C9" "Delivery_Instructions_Line_2", "T0"."C10" "Next_Status", "T0"."C11" "Ordered_Quantity", "T0"."C12" "Ordered_Quantity_LBs", "T0"."C13" "Customer_Segmentation", "T0"."C14" "TM_Name", "T0"."C15" "Make_Site", "T0"."C16" "Lead_Time_Order_to_Ship", "T0"."C17" "Ship_Site", "T0"."C18" "Carrier_Name", "T0"."C19" "Freight_Handling_Code"
 from (
select "ORDER_ACTIVITY"."ORDER_NUMBER" "C0", substr("ORDER_ACTIVITY"."ORDER_LINE_ID", 1+instr("ORDER_ACTIVITY"."ORDER_LINE_ID", ',', -1), 5) "C1", "ORDER_ACTIVITY_MEASURE"."ORDERED_DATE" "C2", "ORDER_ACTIVITY"."DUE_DATE" "C3", "CUSTOMER_SHIP_TO_SALES_REP"."SALES_REP_TYPE_9_NAME" "C4", "CUSTOMER_SHIP_TO"."CUSTOMER_NAME" "C5", "ORDER_ACTIVITY_MEASURE"."ITEM_NUMBER_2ND" "C6", "ORDER_ACTIVITY_MEASURE"."DESCRIPTION_1" "C7", "ORDER_ACTIVITY_MEASURE"."DELIVERY_INSTRUCTIONS_LINE_1" "C8", "ORDER_ACTIVITY_MEASURE"."DELIVERY_INSTRUCTIONS_LINE_2" "C9", "ORDER_ACTIVITY_MEASURE"."NEXT_STATUS" "C10", sum("ORDER_ACTIVITY_MEASURE"."ORDERED_QTY"*"ORDER_ACTIVITY_MEASURE"."SALES_FACTOR") "C11", sum(("ORDER_ACTIVITY_MEASURE"."ORDERED_QTY"*"ORDER_ACTIVITY_MEASURE"."CONVERSION_FACTOR_LB")*"ORDER_ACTIVITY_MEASURE"."SALES_FACTOR") "C12", "SHIP_TO_AC06_CUSTOMER_CATEGORY"."CUSTOMER_TYPE_CODE" "C13", "VENDOR_ALIAS_TM"."MAILING_NAME" "C14", case  when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CIN2' and "ITEM"."STOCK_TYPE_CODE" in (N'S', N'M', N'Q', N'P') then N'Kemper' when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CIN2' and "ITEM"."STOCK_TYPE_CODE" in (N'D') then N'Shell' when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CINC' and "ITEM"."STOCK_TYPE_CODE" in (N'S', N'M', N'Q', N'P') then N'Shell' else N'OTHER' end  "C15", "ITEM"."LEADTIME_MFG" "C16", case  when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CIN2' then N'Kemper' when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CINC' then N'Shell' else N'OTHER' end  "C17", "VENDOR_ALIAS_CARRIER"."VENDOR_NAME" "C18", "ORDER_ACTIVITY_MEASURE"."FREIGHT_HANDLING_CODE_" "C19"
 from "DW_LEGACY"."ORDER_ACTIVITY" "ORDER_ACTIVITY", "DW_LEGACY"."ORDER_ACTIVITY_MEASURES" "ORDER_ACTIVITY_MEASURE", "DW_LEGACY"."CUSTOMER_SALES_REP" "CUSTOMER_SHIP_TO_SALES_REP", "DW_LEGACY"."CUSTOMER" "CUSTOMER_SHIP_TO", "DW_LEGACY"."CUSTOMER_TYPE" "SHIP_TO_AC06_CUSTOMER_CATEGORY", "DW_LEGACY"."VENDOR" "VENDOR_ALIAS_TM", "DW_LEGACY"."ITEM" "ITEM", "DW_LEGACY"."VENDOR" "VENDOR_ALIAS_CARRIER"
 where "ORDER_ACTIVITY"."DUE_DATE" between sysdate - 365 and sysdate+30 and "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID" in (N'CINC', N'CIN2', N'CIN4') and decode("ITEM"."GLOBAL_BULK_ITEM", '-', "ORDER_ACTIVITY_MEASURE"."ITEM_NUMBER_2ND", "ITEM"."GLOBAL_BULK_ITEM") not  in ('IGST', 'CGST', 'SGST', 'CVD', 'ADD') and "ORDER_ACTIVITY"."ORDER_ACTIVITY_SID"="ORDER_ACTIVITY_MEASURE"."ORDER_ACTIVITY_SID" and "ORDER_ACTIVITY_MEASURE"."CUSTOMER_SHIP_TO__ORDER__SID"="CUSTOMER_SHIP_TO"."CUSTOMER_SID" and "CUSTOMER_SHIP_TO_SALES_REP"."CUSTOMER_SALES_REP__CUST_SID"="CUSTOMER_SHIP_TO"."CUSTOMER_SID" and "SHIP_TO_AC06_CUSTOMER_CATEGORY"."CUSTOMER_TYPE_SID"="CUSTOMER_SHIP_TO"."JDE_AIAC06__CUSTOMER_TYP_SID" and "ORDER_ACTIVITY_MEASURE"."ORDER_ACTIVITY__ITEM_SID"="ITEM"."ITEM_SID" and "ORDER_ACTIVITY_MEASURE"."CARRIER_NUMBER_"="VENDOR_ALIAS_CARRIER"."VENDOR_DIM_ID" and "ORDER_ACTIVITY"."SALES_REP_ID"="VENDOR_ALIAS_TM"."VENDOR_DIM_ID"
 group by "ORDER_ACTIVITY"."ORDER_NUMBER", substr("ORDER_ACTIVITY"."ORDER_LINE_ID", 1+instr("ORDER_ACTIVITY"."ORDER_LINE_ID", ',', -1), 5), "ORDER_ACTIVITY_MEASURE"."ORDERED_DATE", "ORDER_ACTIVITY"."DUE_DATE", "CUSTOMER_SHIP_TO_SALES_REP"."SALES_REP_TYPE_9_NAME", "CUSTOMER_SHIP_TO"."CUSTOMER_NAME", "ORDER_ACTIVITY_MEASURE"."ITEM_NUMBER_2ND", "ORDER_ACTIVITY_MEASURE"."DESCRIPTION_1", "ORDER_ACTIVITY_MEASURE"."DELIVERY_INSTRUCTIONS_LINE_1", "ORDER_ACTIVITY_MEASURE"."DELIVERY_INSTRUCTIONS_LINE_2", "ORDER_ACTIVITY_MEASURE"."NEXT_STATUS", "SHIP_TO_AC06_CUSTOMER_CATEGORY"."CUSTOMER_TYPE_CODE", "VENDOR_ALIAS_TM"."MAILING_NAME", case  when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CIN2' and "ITEM"."STOCK_TYPE_CODE" in (N'S', N'M', N'Q', N'P') then N'Kemper' when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CIN2' and "ITEM"."STOCK_TYPE_CODE" in (N'D') then N'Shell' when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CINC' and "ITEM"."STOCK_TYPE_CODE" in (N'S', N'M', N'Q', N'P') then N'Shell' else N'OTHER' end , "ITEM"."LEADTIME_MFG", case  when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CIN2' then N'Kemper' when "ORDER_ACTIVITY_MEASURE"."ORGANIZATION_ID"=N'CINC' then N'Shell' else N'OTHER' end , "VENDOR_ALIAS_CARRIER"."VENDOR_NAME", "ORDER_ACTIVITY_MEASURE"."FREIGHT_HANDLING_CODE_") "T0"
 order by "Promised_Ship_Date" asc nulls last



